--
-- Name: vw_trazabilidad_productos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_trazabilidad_productos AS
 SELECT p.id,
    p.sku,
    p.name,
    l.db_user AS performed_by,
    l.operation,
    l.description,
    l.operation_date
   FROM (public.tb_products p
     JOIN public.tb_logs l ON (((l.table_name = 'tb_products'::text) AND (l.record_id = p.id))));


ALTER VIEW public.vw_trazabilidad_productos OWNER TO postgres;

